pTempDir->AppendRelativePath(u"moz_mapi"_ns);
pTempDir->Exists(&bExist);
if (!bExist) {
  rv = pTempDir->Create(nsIFile::DIRECTORY_TYPE, 0777);
  if (NS_FAILED(rv)) return rv;
